CREATE TABLE IF NOT EXISTS projects(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,description TEXT,url TEXT,image TEXT,goal REAL DEFAULT 0,clicks INTEGER DEFAULT 0,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS images(id INTEGER PRIMARY KEY AUTOINCREMENT,data TEXT);
CREATE TABLE IF NOT EXISTS donations(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id INTEGER,name TEXT,phone TEXT,ref TEXT,amount REAL,status TEXT DEFAULT 'pending',created TEXT DEFAULT CURRENT_TIMESTAMP);
